const WERKZEUG = 'casestore_internal.upsert_case';
const ADAPTER_ID = 'casestore_internal';
const ULID = '[0-9A-HJKMNP-TV-Z]{26}';
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error('adp_casestore_internal_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten ' + alle.length);
}
const e = alle[0].json;
const p = (e.payload && typeof e.payload === 'object' && !Array.isArray(e.payload)) ? e.payload : null;
const fehler = [];
const txt = function (v, min, max) { return typeof v === 'string' && v.length >= min && v.length <= max; };
const zeit = function (v) { return typeof v === 'string' && /Z$/.test(v) && !isNaN(Date.parse(v)); };
const norm = function (v) { return (v === undefined || v === null || v === '') ? null : new Date(v).toISOString().replace(/[.][0-9]{3}Z$/, 'Z'); };
const oder = function (v) { return (v === undefined || v === '') ? null : v; };
const obj = function (v) { return v && typeof v === 'object' && !Array.isArray(v); };
if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(e.context_id || ''))) fehler.push('context_id fehlt oder hat kein gueltiges Format');
if (e.tool_id !== WERKZEUG) fehler.push('tool_id passt nicht zu diesem Adapter');
if (!/^act_[A-Za-z0-9_]{6,64}$/.test(String(e.action_id || ''))) fehler.push('action_id fehlt oder ist ungueltig');
if (!p) {
  fehler.push('payload fehlt');
} else {
  if (p.context_id !== e.context_id) fehler.push('context_mismatch: payload.context_id weicht vom Aufrufkontext ab');
  if (!/^[0-9]+[.][0-9]+[.][0-9]+$/.test(String(p.schema_version || ''))) fehler.push('schema_version ungueltig');
  if (!zeit(p.created_at)) fehler.push('created_at fehlt oder ist kein UTC-Zeitstempel');
  if (!(obj(p.producer) && p.producer.producer_type && p.producer.producer_id)) fehler.push('producer unvollstaendig');
  const TYPEN = ['policy_number', 'contract_number', 'case_number_external', 'customer_number', 'invoice_number', 'reference_number', 'tax_number', 'other'];
  if (!new RegExp('^cse_' + ULID + '$').test(String(p.case_id || ''))) fehler.push('case_id ungueltig');
  if (p.case_number !== undefined && !/^V-[0-9]{4}-[0-9]{4}$/.test(String(p.case_number))) fehler.push('case_number ungueltig');
  if (!txt(p.title, 3, 200)) fehler.push('title fehlt oder Laenge unzulaessig');
  if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(p.category_key || ''))) fehler.push('category_key ungueltig');
  if (['open', 'waiting', 'closed', 'archived'].indexOf(p.status) === -1) fehler.push('status unzulaessig');
  if (p.status === 'closed' && !zeit(p.closed_at)) fehler.push('closed verlangt closed_at');
  if (!zeit(p.opened_at)) fehler.push('opened_at fehlt oder ist kein UTC-Zeitstempel');
  if (p.next_deadline_at !== undefined && p.next_deadline_at !== null && !zeit(p.next_deadline_at)) fehler.push('next_deadline_at ist kein UTC-Zeitstempel');
  if (p.closed_at !== undefined && p.closed_at !== null && !zeit(p.closed_at)) fehler.push('closed_at ist kein UTC-Zeitstempel');
  if (p.identifiers !== undefined) {
    if (!Array.isArray(p.identifiers)) fehler.push('identifiers ist keine Liste');
    else {
      const gesehen = {};
      for (const k of p.identifiers) {
        if (!obj(k) || TYPEN.indexOf(k.identifier_type) === -1 || !txt(k.value_normalized, 2, 100)) { fehler.push('identifiers enthaelt einen ungueltigen Eintrag'); break; }
        if (k.first_seen_document_id !== undefined && !new RegExp('^doc_' + ULID + '$').test(String(k.first_seen_document_id))) { fehler.push('identifiers.first_seen_document_id ungueltig'); break; }
        const s = k.identifier_type + '|' + k.value_normalized;
        if (gesehen[s]) { fehler.push('identifiers enthaelt Dubletten'); break; }
        gesehen[s] = true;
      }
    }
  }
}
let zeile = null;
let erwartet = null;
if (fehler.length === 0) {
  const kennungen = (p.identifiers || []).map(function (k) { return { identifier_type: k.identifier_type, value_normalized: k.value_normalized, issuer: oder(k.issuer), first_seen_document_id: oder(k.first_seen_document_id) }; });
  const vergleich = kennungen.map(function (k) { return { identifier_type: k.identifier_type, value_normalized: k.value_normalized }; })
    .sort(function (a, b) { const x = a.identifier_type + '|' + a.value_normalized; const y = b.identifier_type + '|' + b.value_normalized; return x < y ? -1 : (x > y ? 1 : 0); });
  const body = Object.assign({}, p);
  delete body.case_number;
  zeile = { case_id: p.case_id, schema_version: p.schema_version, context_id: p.context_id, title: p.title, category_key: p.category_key, status: p.status,
    next_deadline_at: oder(p.next_deadline_at), opened_at: p.opened_at, closed_at: oder(p.closed_at), identifiers: kennungen, body: body };
  erwartet = { context_id: p.context_id, title: p.title, category_key: p.category_key, status: p.status, next_deadline_at: norm(p.next_deadline_at),
    opened_at: norm(p.opened_at), closed_at: norm(p.closed_at), identifiers: vergleich };
}
const basis = { adapter_id: ADAPTER_ID, tool_id: WERKZEUG, context_id: e.context_id || null, action_id: e.action_id || null, trace_id: e.trace_id || null };
if (fehler.length > 0) {
  return [{ json: Object.assign({ route: 'invalid', fehler: fehler }, basis) }];
}
return [{ json: Object.assign({ route: e.dry_run === true ? 'dry_run' : e.context_id, requested_id: p.case_id, zeile_b64: Buffer.from(JSON.stringify(zeile), 'utf8').toString('base64'), expected: erwartet }, basis) }];

const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
const basis = { adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, trace_id: e.trace_id };
if (r.found !== true) {
  return [{ json: Object.assign({ status: 'error', write_outcome: r.write_outcome || 'unknown', error: { error_class: 'consistency', error_code: 'readback_missing', retryable: false, message: 'Zielobjekt nach dem Schreiben nicht lesbar' } }, basis) }];
}
const beobachtet = { context_id: r.context_id, title: r.title, category_key: r.category_key, status: r.status, next_deadline_at: r.next_deadline_at || null,
  opened_at: r.opened_at || null, closed_at: r.closed_at || null, identifiers: Array.isArray(r.identifiers) ? r.identifiers : [] };
return [{ json: Object.assign({ status: 'ok', write_outcome: r.write_outcome, case_number: r.case_number, target_object_ref: { object_type: 'case', object_id: r.case_id, requested_id: e.requested_id }, verification_method: 'readback', observed: beobachtet, expected: e.expected }, basis) }];

const e = $input.first().json;
// TS-10: Ohne Fehlerliste kommt der Eintrag aus dem Ausweichausgang der Kontextweiche.
const fehler = (Array.isArray(e.fehler) && e.fehler.length > 0) ? e.fehler : ['context_id ohne Kontextweiche'];
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'none', error: { error_class: 'validation', error_code: 'invalid_input', retryable: false, message: fehler.join('; ') }, trace_id: e.trace_id } }];

const e = $('Eingabe pruefen').first().json;
const f = $input.first().json;
const roh = JSON.stringify(f.error || f).slice(0, 2000);
let klasse = 'unknown';
let code = 'db_error';
let wiederholbar = false;
if (/42501|permission denied/i.test(roh)) { klasse = 'permission'; code = 'permission_denied'; }
else if (/23505|duplicate key/i.test(roh)) { klasse = 'conflict'; code = 'unique_violation'; }
else if (/23514|check constraint/i.test(roh)) { klasse = 'validation'; code = 'constraint_violation'; }
else if (/23503|foreign key/i.test(roh)) { klasse = 'validation'; code = 'reference_missing'; }
else if (/timeout|timed out|ETIMEDOUT/i.test(roh)) { klasse = 'timeout'; code = 'db_timeout'; wiederholbar = true; }
else if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|terminat|connection/i.test(roh)) { klasse = 'transient_network'; code = 'db_unreachable'; wiederholbar = true; }
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'unknown', error: { error_class: klasse, error_code: code, retryable: wiederholbar, message: roh.slice(0, 500) }, trace_id: e.trace_id } }];
